// === Tab: Spore ===
class Spore {
	constructor(pos, a) {
		this.pos = pos;
		this.a = a;
		this.len = 0;
		this.alive = true;
		this.count = random(90, 120);
		this.str = random(5, 20);
		this.sw = 2;
		this.d = map(this.pos.dist(center), 0, height / 2, 255, 0);
	}
	show() {
		stroke(this.str, 90);
		strokeWeight(this.sw);
		push();
		translate(this.pos);
		point(0, 0);
		if (this.count < 5) {
			this.alive = false;
			stroke(this.d);
			strokeWeight(random(4, 7));
			point(0, 0);
			if (spawning) spawn(this.pos, 2, 5);
		}
		pop();
		if (this.count < 70) {
			this.sw *= 0.99;
			this.str *= 1.1;
			this.a += (0.48 - noise(this.pos.x, this.pos.y, this.count));
			this.pos.x += cos(this.a);
			this.pos.y += sin(this.a);
		}
		this.count -= 1
	}
}

