// For the #WCCChallenge, theme: "petri dish".
// Inspired by this amazing short YouTube film 
// "The Rise of Molds" https://www.youtube.com/watch?v=IQ8Br_sUfI8

let spores = [];
let spawning = true;
let center;
let zoom;

function setup() {
	createCanvas(windowWidth, windowHeight);
	zoom = height/600;
	background(255);
	strokeWeight(3);
	center = createVector(0,0);
	for (let r = 1.95 * height; r > 0; r -= height / 40) {
		noStroke();
		fill(map(r, 0, 1.95 * height, 20, 225));
		ellipse(width / 2, height / 2, r, r);
	}
	filter(BLUR,8);
	noFill();
	stroke(255);
	ellipse(width / 2, height / 2, 1.95 * height,1.95 * height);
}

function draw() {
	if(frameCount<90 && frameCount%10==0) spawn(center, 4, random(30))
	if (frameCount > 800) spawning = false;
	beginClip();
	ellipse(width / 2, height / 2, 1.95 * height, 1.95 * height);
	endClip();
	translate(width / 2, height / 2);
	scale(zoom);
	spores = spores.filter(s => s.alive);
	for (let s of spores) {
		s.show();
	}
	if(spawning && frameCount%120==0) filter(BLUR,1);
}

function spawn(spawnpos, num, spread) {
	for (let i = 0; i < num; i++) {
		let sporepos = p5.Vector.random2D().mult(spread);
		let a = sporepos.heading();
		sporepos.x += spawnpos.x;
		sporepos.y += spawnpos.y;
		let s = new Spore(sporepos, a);
		spores.push(s);
	}
}

function mousePressed() {
	spores = [];
	frameCount = 0;
	spawning = true;
	center.x = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2)/zoom;
	center.y= ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2)/zoom;
}

